configFiles.winfsp-setup.ps1:
# WinFsp ships only as a kernel-mode driver package plus the WinFsp.Launcher
# service; there is no portable payload to extract. This entry point opens the
# vendor MSI exactly as a double-click would. Windows raises its own UAC prompt
# and wizard, nothing is installed until the user confirms there, and Piko never
# runs msiexec on its own.
$msi = Join-Path $PSScriptRoot 'winfsp.msi'
if (!(Test-Path -LiteralPath $msi -PathType Leaf)) {
  throw ('WinFsp installer payload is missing: ' + $msi)
}
if ($args.Count) {
  throw 'winfsp-setup opens the interactive installer only; run msiexec directly for an unattended install'
}
Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\msiexec.exe') -ArgumentList @('/i', ('"' + $msi + '"')) | Out-Null
